package org.peirs.config;
import org.peirs.model.*; import org.peirs.repo.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.security.crypto.password.PasswordEncoder; import java.math.BigDecimal; import java.util.List;
@Configuration public class SeedData {
 @Bean CommandLineRunner seed(UserRepository users,ProjectRepository projects,CriterionRepository criteria,EvaluationRepository evaluations,EvaluationScoreRepository scores,PasswordEncoder encoder){return args->{
  if(users.count()==0){users.save(new User("System Admin","admin@peirs.local",encoder.encode("ChangeMe123!"),"ADMIN"));users.save(new User("Morgan Evaluator","evaluator@peirs.local",encoder.encode("ChangeMe123!"),"EVALUATOR"));users.save(new User("Project Owner","owner@peirs.local",encoder.encode("ChangeMe123!"),"PROJECT_OWNER"));users.save(new User("Investment Manager","manager@peirs.local",encoder.encode("ChangeMe123!"),"INVESTMENT_MANAGER"));}
  if(criteria.count()==0){criteria.save(new Criterion("Financial Viability",25));criteria.save(new Criterion("Strategic Alignment",20));criteria.save(new Criterion("Technical Feasibility",15));criteria.save(new Criterion("Expected Impact",15));criteria.save(new Criterion("Risk Assessment",15));criteria.save(new Criterion("Implementation Feasibility",10));}
  if(projects.count()==0){String[] names={"Grid Modernization Phase II","Solar Campus Network","ERP Transformation","Regional Care Expansion","Smart Manufacturing Cell","Materials Research Lab","Digital Services Renewal","Transit Corridor Upgrade","Zero Trust Security","Connected Learning Initiative","Water Resilience Program","Logistics Optimization Hub"};String[] cats={"Infrastructure","Renewable Energy","Enterprise Software","Healthcare","Manufacturing","Research & Development","Digital Transformation","Transportation","Cybersecurity","Education","Infrastructure","Operations"};String[] depts={"Facilities","Energy","Technology","Health","Operations","Research","Technology","Transport","Technology","Education","Facilities","Operations"};double[] inv={8200000,4100000,3600000,11500000,5400000,2900000,2200000,14800000,1750000,1300000,6800000,3400000};double[] rev={2100000,1150000,1250000,3300000,1800000,900000,950000,3600000,750000,480000,1900000,1400000};for(int i=0;i<names.length;i++){Project p=new Project();p.projectCode="PEI-%04d".formatted(i+1);p.title=names[i];p.category=cats[i];p.department=depts[i];p.description="A multi-year investment proposal designed to improve organizational capability and measurable public value.";p.objectives="Improve service quality, resilience and long-term operating efficiency.";p.expectedOutcomes="Measurable performance gains with annual benefit tracking.";p.investment=BigDecimal.valueOf(inv[i]);p.annualRevenue=BigDecimal.valueOf(rev[i]);p.annualCost=BigDecimal.valueOf(rev[i]*.32);p.lifespanYears=6;p.timelineMonths=12+i%18;p.strategicImportance=62+(i*7)%37;p.technicalFeasibility=65+(i*11)%31;p.status=i<4?"EVALUATED":"SUBMITTED";p=projects.save(p);if(i<4){List<Criterion> cs=criteria.findByEnabledTrue();double[] raw={86-i*8,p.strategicImportance,p.technicalFeasibility,80-i*4,74-i*6,78-i*3};double overall=0;for(int j=0;j<cs.size();j++)overall+=raw[j]*cs.get(j).weight.doubleValue()/100;User evaluator=users.findByEmail("evaluator@peirs.local").orElseThrow();Evaluation e=new Evaluation();e.project=p;e.evaluator=evaluator;e.overallScore=BigDecimal.valueOf(overall);e.financialScore=BigDecimal.valueOf(raw[0]);e.riskScore=BigDecimal.valueOf(18+i*14);e.comments="Seeded demonstration evaluation with criterion-level scores.";e=evaluations.save(e);for(int j=0;j<cs.size();j++)scores.save(new EvaluationScore(e,cs.get(j),raw[j]));}}}
 };}
}
